package org.hibernate.dialect.testing;

import java.util.List;
import java.util.Objects;

import org.hibernate.Incubating;
import org.hibernate.SPI;

import static org.hibernate.SPI.Role.USE;

/// One immutable SQL statement generated by the test kit.
///
/// @author Steve Ebersole
/// @since 8.0
@Incubating
@SPI(USE)
public record GeneratedStatement(String sql, List<GeneratedParameter> parameters) {
	public GeneratedStatement {
		sql = Objects.requireNonNull( sql, "sql" );
		parameters = List.copyOf( Objects.requireNonNull( parameters, "parameters" ) );
	}
}
